SELECT 526, '데이터 모델링 기초 (2) 정규화와 반정규화: 이상 현상, 1NF·2NF·3NF, 표 쪼개기', '표 하나에 모든 정보를 넣으면 생기는 이상 현상(삽입·갱신·삭제)을 보고, 1NF(한 칸에 값 하나)·2NF(부분 종속 제거)·3NF(이행 종속 제거)로 한 단계씩 쪼갭니다. CREATE TABLE 과 INSERT ... SELECT 로 큰 표를 두 표로 나눠 JOIN 으로 확인하고, 반정규화를 고르는 이유와 위험까지 익힙니다.', 'linux-db', '데이터베이스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 526);
UPDATE quest_set SET display_order = 747, unit_id = (SELECT id FROM unit WHERE id = 46), icon = '🧩' WHERE id = 526;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 1, '이상 현상: 삭제하다가 정보가 사라진다', '모든 정보를 한 표에 넣은 `주문(주문번호, 고객, 고객 도시, 상품)` 표가 있습니다. 주문이 딱 한 건뿐인 고객의 그 주문을 **삭제**했더니, **그 고객의 도시 정보까지 함께 사라졌습니다.** 이런 문제를 무엇이라고 할까요?', '이상 현상은 삽입·갱신·삭제 중 어느 동작에서 문제가 터졌는지로 이름 붙입니다.', NULL, NULL, '[]', 'choice', '["삽입 이상", "갱신 이상", "조회 이상", "삭제 이상"]', 3, '한 표에 서로 다른 사실(주문, 고객)이 섞여 있으면 하나를 지울 때 다른 사실까지 사라지는 **삭제 이상**이 생깁니다. 같은 이유로 주문 없는 고객을 먼저 넣을 수 없는 것은 **삽입 이상**, 같은 고객 정보가 여러 행에 있어 일부만 고치면 어긋나는 것은 **갱신 이상**입니다. 조회 이상이라는 용어는 쓰지 않습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 2, '갱신 이상 찾아내기', '`shop` 데이터베이스의 `sales_dirty` 는 주문마다 고객 이름과 도시를 **그대로 반복해서** 적어 둔 표입니다. 누군가 고객 도시가 바뀌어 일부 행만 고친 모양입니다. `customer_id` 별로 묶어서 **도시가 둘 이상으로 다르게 적힌 고객의 이름**을 `/tmp/conflict.txt` 에 저장하세요. (제목 줄 없이 이름만)', '`customer_id` 별로 묶어 도시가 몇 종류 적혀 있는지 세고, 둘 이상인 묶음만 남깁니다. 이름은 `MIN(customer_name)` 처럼 묶음 함수로 뽑을 수 있습니다.', 'mariadb -N shop -e ''SELECT MIN(customer_name) FROM sales_dirty GROUP BY customer_id HAVING COUNT(DISTINCT customer_city) > 1'' > /tmp/conflict.txt
cat /tmp/conflict.txt

# 같은 고객 정보가 여러 행에 반복되면 일부만 고쳤을 때 값이 어긋난다 (갱신 이상). 고객 정보를 한 곳에만 두면 이 문제가 없다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE sales (order_id INT PRIMARY KEY, customer_id INT, customer_name VARCHAR(20), customer_city VARCHAR(20), product VARCHAR(20), price INT); INSERT INTO sales VALUES (1,1,\\"kim\\",\\"Seoul\\",\\"keyboard\\",30000),(2,1,\\"kim\\",\\"Seoul\\",\\"mouse\\",15000),(3,2,\\"lee\\",\\"Busan\\",\\"monitor\\",200000),(4,2,\\"lee\\",\\"Busan\\",\\"mouse\\",15000),(5,3,\\"park\\",\\"Daegu\\",\\"keyboard\\",30000),(6,1,\\"kim\\",\\"Seoul\\",\\"monitor\\",200000); CREATE TABLE sales_dirty (order_id INT PRIMARY KEY, customer_id INT, customer_name VARCHAR(20), customer_city VARCHAR(20), product VARCHAR(20)); INSERT INTO sales_dirty VALUES (1,1,\\"kim\\",\\"Seoul\\",\\"keyboard\\"),(2,2,\\"lee\\",\\"Busan\\",\\"monitor\\"),(3,1,\\"kim\\",\\"Busan\\",\\"mouse\\"),(4,3,\\"park\\",\\"Daegu\\",\\"mouse\\"); CREATE TABLE contacts_raw (name VARCHAR(20), phones VARCHAR(60)); INSERT INTO contacts_raw VALUES (\\"kim\\",\\"010-1111-0001,010-1111-0002\\"),(\\"lee\\",\\"010-2222-0003\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/conflict.txt ] ) && ( [ \\"$(cat /tmp/conflict.txt)\\" = kim ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/conflict.txt ]"]}, {"label": "도시가 어긋난 고객 kim 하나만 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/conflict.txt)\\" = kim ]"]}]', '[{"title": "MariaDB 데이터베이스 정규화", "url": "https://mariadb.com/kb/en/database-normalization/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 3, '1NF: 한 칸에 값 하나만', '1NF(제1정규형)는 **모든 칸이 더 이상 쪼갤 수 없는 값 하나만** 갖는 것입니다. `shop` 의 `contacts_raw` 는 `phones` 한 칸에 번호를 쉼표로 여러 개 적어 이 조건을 어깁니다(kim 은 번호 2개, lee 는 1개). 한 칸에 값 하나씩이 되도록 `contact_phone` 표(열: `name`, `phone`)를 **새로 만들고** 번호 3개를 한 줄씩 넣으세요.', '`CREATE TABLE contact_phone (name ..., phone ...)` 으로 만든 뒤 `INSERT ... VALUES` 에 `contacts_raw` 에서 본 번호를 한 행에 하나씩 적습니다. 먼저 `SELECT * FROM contacts_raw` 로 내용을 확인하세요.', 'mariadb shop -e ''CREATE TABLE contact_phone (name VARCHAR(20), phone VARCHAR(20)); INSERT INTO contact_phone VALUES ("kim","010-1111-0001"),("kim","010-1111-0002"),("lee","010-2222-0003");''
mariadb shop -e ''SELECT * FROM contact_phone''

# 번호 하나가 한 행이 되어 칸마다 값이 하나다 (1NF). 번호가 늘어도 열을 바꾸지 않고 행만 추가하면 된다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE sales (order_id INT PRIMARY KEY, customer_id INT, customer_name VARCHAR(20), customer_city VARCHAR(20), product VARCHAR(20), price INT); INSERT INTO sales VALUES (1,1,\\"kim\\",\\"Seoul\\",\\"keyboard\\",30000),(2,1,\\"kim\\",\\"Seoul\\",\\"mouse\\",15000),(3,2,\\"lee\\",\\"Busan\\",\\"monitor\\",200000),(4,2,\\"lee\\",\\"Busan\\",\\"mouse\\",15000),(5,3,\\"park\\",\\"Daegu\\",\\"keyboard\\",30000),(6,1,\\"kim\\",\\"Seoul\\",\\"monitor\\",200000); CREATE TABLE sales_dirty (order_id INT PRIMARY KEY, customer_id INT, customer_name VARCHAR(20), customer_city VARCHAR(20), product VARCHAR(20)); INSERT INTO sales_dirty VALUES (1,1,\\"kim\\",\\"Seoul\\",\\"keyboard\\"),(2,2,\\"lee\\",\\"Busan\\",\\"monitor\\"),(3,1,\\"kim\\",\\"Busan\\",\\"mouse\\"),(4,3,\\"park\\",\\"Daegu\\",\\"mouse\\"); CREATE TABLE contacts_raw (name VARCHAR(20), phones VARCHAR(60)); INSERT INTO contacts_raw VALUES (\\"kim\\",\\"010-1111-0001,010-1111-0002\\"),(\\"lee\\",\\"010-2222-0003\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM contact_phone\\")\\" = 3 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM contact_phone WHERE phone LIKE ''%,%''\\")\\" = 0 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM contact_phone WHERE name=''kim''\\")\\" = 2 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM contact_phone WHERE phone IN (''010-1111-0001'',''010-1111-0002'',''010-2222-0003'')\\")\\" = 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3행이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM contact_phone\\")\\" = 3 ]"]}, {"label": "쉼표가 든 칸이 없다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM contact_phone WHERE phone LIKE ''%,%''\\")\\" = 0 ]"]}, {"label": "kim 은 두 행이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM contact_phone WHERE name=''kim''\\")\\" = 2 ]"]}, {"label": "원래 번호가 들어 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM contact_phone WHERE phone IN (''010-1111-0001'',''010-1111-0002'',''010-2222-0003'')\\")\\" = 3 ]"]}]', '[{"title": "MariaDB 데이터베이스 정규화", "url": "https://mariadb.com/kb/en/database-normalization/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 4, '2NF: 부분 종속인 열 찾기', '`주문상세(주문번호, 상품번호, 상품명, 수량)` 표의 기본키는 **(주문번호, 상품번호) 두 열의 묶음**입니다. 상품명은 **상품번호만 알아도** 정해지고, 수량은 두 열을 모두 알아야 정해집니다. 2NF(제2정규형)를 어기게 만드는, 기본키 **일부에만 종속된 열**은 무엇일까요?', '기본키를 이루는 열은 후보에서 제외됩니다. 기본키가 아닌 열 중에서, 키의 한쪽만으로 값이 정해지는 것을 고르세요.', NULL, NULL, '[]', 'choice', '["상품명", "수량", "주문번호", "상품번호"]', 0, '2NF 는 1NF 를 만족하면서 **기본키가 아닌 모든 열이 기본키 전체에 종속**되는 것입니다. 상품명은 키의 일부(상품번호)에만 종속되는 **부분 종속**이라 2NF 를 어기고, `상품(상품번호, 상품명)` 표로 분리해 해결합니다. 수량은 두 열 전체에 종속돼 문제없고, 주문번호·상품번호는 기본키 자체입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 5, '3NF: 이행 종속', 'A 를 알면 B 가 정해지고, B 를 알면 C 가 정해져서 결국 A 가 B 를 **거쳐서** C 를 결정하는 관계가 있습니다. 3NF(제3정규형)는 기본키가 아닌 열 사이에 이런 종속이 없게 만듭니다. 빈칸을 채우세요.', '키의 일부에 걸린 종속은 "부분 종속"이라 부릅니다. 여기서는 중간 열을 거쳐 이어지는 종속입니다.', NULL, NULL, '[]', 'fill', '["이행", "부분", "완전", "다치"]', NULL, '중간 열을 거쳐 이어지는 종속을 **이행 종속**이라 하고, 3NF 는 2NF 를 만족하면서 기본키가 아닌 열이 기본키에 이행 종속되지 않게 합니다. 부분 종속은 2NF, 완전 종속은 2NF 가 요구하는 바람직한 상태, 다치 종속은 더 높은 단계(4NF)의 개념입니다.', '[0]', 'A → B 이고 B → C 이면, A → C 는 B 를 거친 {0} 종속이며 3NF 는 이를 없앤다.', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 6, '3NF: 어떻게 쪼갤까', '`학생(학번, 학과코드, 학과명)` 표의 기본키는 학번입니다. 학번을 알면 학과코드가 정해지고, 학과코드를 알면 학과명이 정해집니다(이행 종속). 3NF 를 만족하도록 가장 올바르게 나눈 것은?', '정보를 잃지 않고, 학과명이 한 곳에만 저장되게 나누는 방법입니다.', NULL, NULL, '[]', 'choice', '["학과명 열을 삭제하고 어디에도 저장하지 않는다", "학과코드 열을 학과명 칸에 쉼표로 함께 적는다", "`학생(학번, 학과코드)` 와 `학과(학과코드, 학과명)`", "`학생` 표에 학과별 인원 수 열을 추가한다"]', 2, '학과명을 결정하는 것은 학번이 아니라 학과코드이므로 `학과(학과코드, 학과명)` 으로 떼어 내고 학생 표에는 학과코드만 남깁니다. 학과명이 한 곳에만 있어 이름이 바뀌어도 한 행만 고치면 됩니다. 열을 지우면 정보가 사라지고, 쉼표로 묶으면 1NF 를 어기며, 인원 수 열은 문제와 관계없습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 7, '실제로 쪼개기 (1): 고객 표 만들기', '`shop` 의 `sales` 표는 주문마다 `customer_name`, `customer_city` 를 반복합니다. 고객 이름과 도시는 `customer_id` 만 알면 정해지는 **이행 종속**입니다. 먼저 고객 정보를 따로 모으세요. `customers` 표(열: `customer_id` 기본키, `customer_name`, `customer_city`)를 **`CREATE TABLE`** 로 만들고, `INSERT ... SELECT DISTINCT` 로 `sales` 에서 **중복 없이** 채우세요. (고객 3명)', '먼저 `CREATE TABLE customers (...)` 로 열을 정의하고, `INSERT INTO customers SELECT DISTINCT 열1, 열2, 열3 FROM sales` 로 채웁니다. `DISTINCT` 가 같은 고객의 반복을 하나로 줄입니다.', 'mariadb shop -e ''CREATE TABLE customers (customer_id INT PRIMARY KEY, customer_name VARCHAR(20), customer_city VARCHAR(20)); INSERT INTO customers SELECT DISTINCT customer_id, customer_name, customer_city FROM sales;''
mariadb shop -e ''SELECT * FROM customers''

# 반복되던 고객 정보를 한 곳으로 모은다. 6개 주문 행이 고객 3행이 된다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE sales (order_id INT PRIMARY KEY, customer_id INT, customer_name VARCHAR(20), customer_city VARCHAR(20), product VARCHAR(20), price INT); INSERT INTO sales VALUES (1,1,\\"kim\\",\\"Seoul\\",\\"keyboard\\",30000),(2,1,\\"kim\\",\\"Seoul\\",\\"mouse\\",15000),(3,2,\\"lee\\",\\"Busan\\",\\"monitor\\",200000),(4,2,\\"lee\\",\\"Busan\\",\\"mouse\\",15000),(5,3,\\"park\\",\\"Daegu\\",\\"keyboard\\",30000),(6,1,\\"kim\\",\\"Seoul\\",\\"monitor\\",200000); CREATE TABLE sales_dirty (order_id INT PRIMARY KEY, customer_id INT, customer_name VARCHAR(20), customer_city VARCHAR(20), product VARCHAR(20)); INSERT INTO sales_dirty VALUES (1,1,\\"kim\\",\\"Seoul\\",\\"keyboard\\"),(2,2,\\"lee\\",\\"Busan\\",\\"monitor\\"),(3,1,\\"kim\\",\\"Busan\\",\\"mouse\\"),(4,3,\\"park\\",\\"Daegu\\",\\"mouse\\"); CREATE TABLE contacts_raw (name VARCHAR(20), phones VARCHAR(60)); INSERT INTO contacts_raw VALUES (\\"kim\\",\\"010-1111-0001,010-1111-0002\\"),(\\"lee\\",\\"010-2222-0003\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM customers\\")\\" = 3 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''customers'' AND column_name=''customer_id'' AND column_key=''PRI''\\")\\" = 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "고객이 3행이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM customers\\")\\" = 3 ]"]}, {"label": "customer_id 가 기본키다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''customers'' AND column_name=''customer_id'' AND column_key=''PRI''\\")\\" = 1 ]"]}]', '[{"title": "MariaDB 데이터베이스 정규화", "url": "https://mariadb.com/kb/en/database-normalization/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 8, '실제로 쪼개기 (2): 주문 표 만들기', '이제 주문 쪽입니다. `orders` 표(열: `order_id` 기본키, `customer_id`, `product`, `price`)를 `CREATE TABLE` 로 만들고 `sales` 에서 `INSERT ... SELECT` 로 **6건 모두** 옮기세요. 고객 이름·도시는 `customers` 에 있으므로 `orders` 에는 **넣지 않습니다.** (`customer_id` 로 고객을 찾습니다)', '`INSERT INTO orders SELECT 열들 FROM sales` 의 열 순서는 `orders` 를 만들 때 정한 열 순서와 같아야 합니다. 이름·도시 열은 가져오지 않습니다.', 'mariadb shop -e ''CREATE TABLE orders (order_id INT PRIMARY KEY, customer_id INT, product VARCHAR(20), price INT); INSERT INTO orders SELECT order_id, customer_id, product, price FROM sales;''
mariadb shop -e ''SELECT * FROM orders''

# 주문 표에는 고객을 가리키는 번호만 남기고 이름·도시는 빠진다. 고객 정보가 한 곳에만 있게 된다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE sales (order_id INT PRIMARY KEY, customer_id INT, customer_name VARCHAR(20), customer_city VARCHAR(20), product VARCHAR(20), price INT); INSERT INTO sales VALUES (1,1,\\"kim\\",\\"Seoul\\",\\"keyboard\\",30000),(2,1,\\"kim\\",\\"Seoul\\",\\"mouse\\",15000),(3,2,\\"lee\\",\\"Busan\\",\\"monitor\\",200000),(4,2,\\"lee\\",\\"Busan\\",\\"mouse\\",15000),(5,3,\\"park\\",\\"Daegu\\",\\"keyboard\\",30000),(6,1,\\"kim\\",\\"Seoul\\",\\"monitor\\",200000); CREATE TABLE sales_dirty (order_id INT PRIMARY KEY, customer_id INT, customer_name VARCHAR(20), customer_city VARCHAR(20), product VARCHAR(20)); INSERT INTO sales_dirty VALUES (1,1,\\"kim\\",\\"Seoul\\",\\"keyboard\\"),(2,2,\\"lee\\",\\"Busan\\",\\"monitor\\"),(3,1,\\"kim\\",\\"Busan\\",\\"mouse\\"),(4,3,\\"park\\",\\"Daegu\\",\\"mouse\\"); CREATE TABLE contacts_raw (name VARCHAR(20), phones VARCHAR(60)); INSERT INTO contacts_raw VALUES (\\"kim\\",\\"010-1111-0001,010-1111-0002\\"),(\\"lee\\",\\"010-2222-0003\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM orders\\")\\" = 6 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name IN (''customer_name'',''customer_city'')\\")\\" = 0 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "주문이 6행이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM orders\\")\\" = 6 ]"]}, {"label": "이름·도시 열이 없다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name IN (''customer_name'',''customer_city'')\\")\\" = 0 ]"]}]', '[{"title": "MariaDB 데이터베이스 정규화", "url": "https://mariadb.com/kb/en/database-normalization/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 9, '쪼갠 표를 JOIN 으로 다시 합치기', '표를 나눠도 정보는 사라지지 않았을까요? 이번 환경은 `sales` 가 이미 `customers`(고객)와 `orders`(주문) 두 표로 나뉘어 있고 **원래 표는 지워진 상태**입니다. `orders` 와 `customers` 를 `customer_id` 로 `JOIN` 해서 **주문번호, 고객 이름, 도시, 상품, 가격** 순서의 열을 **주문번호 순**으로 `/tmp/joined.txt` 에 저장하세요. (제목 줄 없이, 6줄)', '`FROM orders o JOIN customers c ON o.customer_id = c.customer_id` 로 잇고, 열은 설명에 나온 순서대로 고릅니다. 정렬은 맨 끝의 `ORDER BY` 입니다.', 'mariadb -N shop -e ''SELECT o.order_id, c.customer_name, c.customer_city, o.product, o.price FROM orders o JOIN customers c ON o.customer_id = c.customer_id ORDER BY o.order_id'' > /tmp/joined.txt
cat /tmp/joined.txt

# JOIN 으로 원래의 큰 표와 같은 결과가 복원된다. 정규화는 정보를 버리는 것이 아니라 나눠 저장하는 것이다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE sales (order_id INT PRIMARY KEY, customer_id INT, customer_name VARCHAR(20), customer_city VARCHAR(20), product VARCHAR(20), price INT); INSERT INTO sales VALUES (1,1,\\"kim\\",\\"Seoul\\",\\"keyboard\\",30000),(2,1,\\"kim\\",\\"Seoul\\",\\"mouse\\",15000),(3,2,\\"lee\\",\\"Busan\\",\\"monitor\\",200000),(4,2,\\"lee\\",\\"Busan\\",\\"mouse\\",15000),(5,3,\\"park\\",\\"Daegu\\",\\"keyboard\\",30000),(6,1,\\"kim\\",\\"Seoul\\",\\"monitor\\",200000); CREATE TABLE sales_dirty (order_id INT PRIMARY KEY, customer_id INT, customer_name VARCHAR(20), customer_city VARCHAR(20), product VARCHAR(20)); INSERT INTO sales_dirty VALUES (1,1,\\"kim\\",\\"Seoul\\",\\"keyboard\\"),(2,2,\\"lee\\",\\"Busan\\",\\"monitor\\"),(3,1,\\"kim\\",\\"Busan\\",\\"mouse\\"),(4,3,\\"park\\",\\"Daegu\\",\\"mouse\\"); CREATE TABLE contacts_raw (name VARCHAR(20), phones VARCHAR(60)); INSERT INTO contacts_raw VALUES (\\"kim\\",\\"010-1111-0001,010-1111-0002\\"),(\\"lee\\",\\"010-2222-0003\\");''; mariadb shop -e ''CREATE TABLE customers (customer_id INT PRIMARY KEY, customer_name VARCHAR(20), customer_city VARCHAR(20)); INSERT INTO customers SELECT DISTINCT customer_id, customer_name, customer_city FROM sales; CREATE TABLE orders (order_id INT PRIMARY KEY, customer_id INT, product VARCHAR(20), price INT); INSERT INTO orders SELECT order_id, customer_id, product, price FROM sales; DROP TABLE sales;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/joined.txt)\\" = 6 ] ) && ( awk -F\\"\\\\t\\" ''$1==6 && $2==\\"kim\\" && $3==\\"Seoul\\" && $4==\\"monitor\\" && $5==200000'' /tmp/joined.txt | grep -q . ) && ( LC_ALL=C sort -n -c /tmp/joined.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "6줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/joined.txt)\\" = 6 ]"]}, {"label": "주문 6번은 kim·Seoul·monitor 다", "cmd": ["sh", "-c", "awk -F\\"\\\\t\\" ''$1==6 && $2==\\"kim\\" && $3==\\"Seoul\\" && $4==\\"monitor\\" && $5==200000'' /tmp/joined.txt | grep -q ."]}, {"label": "주문번호 순이다", "cmd": ["sh", "-c", "LC_ALL=C sort -n -c /tmp/joined.txt"]}]', '[{"title": "MariaDB 데이터베이스 정규화", "url": "https://mariadb.com/kb/en/database-normalization/"}, {"title": "MariaDB INSERT ... SELECT", "url": "https://mariadb.com/kb/en/insert-select/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 10, '정규화 단계 순서', '표를 정규화할 때 거치는 세 단계를 **정규형 번호가 낮은 것부터** 순서대로 놓으세요.', '각 정규형은 "앞 단계를 만족한 상태에서"라는 조건 위에 정의됩니다.', NULL, NULL, '[]', 'order', '["3NF: 기본키가 아닌 열 사이의 이행 종속을 분리한다", "1NF: 한 칸에 값 하나만 남긴다", "2NF: 기본키 일부에만 종속된 열을 분리한다"]', NULL, '1NF(한 칸에 값 하나) → 2NF(부분 종속 제거) → 3NF(이행 종속 제거) 순서입니다. 2NF 는 1NF 를, 3NF 는 2NF 를 만족한다는 전제 위에서 정의됩니다.', '[1, 2, 0]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 11, '반정규화를 하는 이유', '정규화한 표는 데이터가 한 곳에만 있어 깔끔하지만, 조회할 때 `JOIN` 이 여러 번 필요합니다. 일부러 정규화를 되돌려 **같은 값을 중복해서 두는** 반정규화를 선택하는 가장 대표적인 이유는?', '반정규화는 정확성이 아니라 다른 것을 얻으려는 선택입니다.', NULL, NULL, '[]', 'choice', '["저장 공간을 줄이려고", "자주 읽는 조회에서 JOIN 을 줄여 읽기 속도를 높이려고", "갱신 이상을 없애려고", "기본키를 쓰지 않으려고"]', 1, '반정규화는 조회가 압도적으로 많고 `JOIN` 이 병목일 때 중복을 허용해 읽기 성능을 얻는 선택입니다. 중복이 늘어 저장 공간은 오히려 커지고, 갱신 이상은 다시 생길 수 있습니다. 기본키는 그대로 필요합니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 526, 12, '반정규화의 위험', '주문 표에 `customer_city` 를 다시 복사해 두는 반정규화를 했습니다. 이 선택에서 **가장 조심해야 할 위험**은?', '정규화가 막아 주던 문제가 다시 돌아옵니다.', NULL, NULL, '[]', 'choice', '["고객 도시가 바뀔 때 복사본을 빠뜨리면 값이 서로 어긋난다", "`JOIN` 을 더 많이 써야 해서 조회가 느려진다", "1NF 를 만족할 수 없게 된다", "표를 만들 수 없게 된다"]', 0, '같은 값이 여러 곳에 있으니 원본을 고칠 때 복사본까지 함께 고쳐야 하고, 하나라도 빠뜨리면 **갱신 이상**처럼 값이 어긋납니다. 그래서 반정규화는 어긋남을 막을 방법(함께 갱신하는 코드·트리거·정기 점검 등)과 함께 필요한 곳에만 씁니다. JOIN 이 줄어드는 것이 목적이고, 복사한 열도 한 칸에 값 하나라 1NF 는 어기지 않습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 526 AND order_index = 12);
